import{createClient}from'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';import{SUPABASE_URL,SUPABASE_ANON_KEY,FILE_BUCKET,CUSTOMER_APP_URL}from'./config.js';
const sb=createClient(SUPABASE_URL,SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let session,user,admin,route='dashboard',companies=[],plans=[],accounts=[],currentTicket=null,modalHandler=null,handlingPop=false;
const fmtBytes=n=>{let v=Number(n)||0,i=0,u=['B','KB','MB','GB','TB'];while(v>=1024&&i<u.length-1){v/=1024;i++}return`${v<10&&i?v.toFixed(1):Math.round(v)} ${u[i]}`},fmtNum=n=>new Intl.NumberFormat().format(Number(n)||0),date=v=>v?new Date(v).toLocaleString():'—';
function toast(t){const x=$('#adminToast');x.textContent=t;x.classList.add('show');clearTimeout(x.t);x.t=setTimeout(()=>x.classList.remove('show'),2600)}
function loading(t='Loading…'){$('#adminContent').innerHTML=`<div class="loading"><span class="spinner"></span><p>${esc(t)}</p></div>`}function errorView(e,retry='navigate()'){$('#adminContent').innerHTML=`<div class="error"><h2>Request failed</h2><p>${esc(e.message||e)}</p><button onclick="${retry}">Retry</button></div>`}
function badge(v){return`<span class="badge ${esc(String(v||'').toLowerCase())}">${esc(v||'—')}</span>`}function meter(used,limit){const p=limit?Math.min(100,Math.round(Number(used)/Number(limit)*100)):0;return`<div class="meter"><i style="width:${p}%"></i></div><small>${p}%</small>`}
async function init(){
  const r=await sb.auth.getSession();
  session=r.data.session;
  $('#boot').hidden=true;
  if(!session) return showLogin();
  if(pmRecovery) {
    showResetPw();
    return;
  }
  await enter();
}
function showLogin(){$('#login').hidden=false;$('#adminApp').hidden=true}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginMessage').textContent='Signing in…';const r=await sb.auth.signInWithPassword({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value});$('#loginMessage').textContent=r.error?.message||''};

$('#forgotPasswordBtn').onclick = async () => {
  const email = $('#loginEmail').value.trim();
  if(!email) {
    $('#loginMessage').textContent = 'Enter your email address above to reset password.';
    return;
  }
  $('#loginMessage').textContent = 'Requesting reset link...';
  const r = await sb.auth.resetPasswordForEmail(email, {
    redirectTo: window.location.origin + window.location.pathname
  });
  if (r.error) {
    $('#loginMessage').textContent = r.error.message;
  } else {
    $('#loginMessage').textContent = 'Password reset link sent to your email.';
  }
};



let pmRecovery = false;
try { 
  const hash = window.location.hash || '';
  const search = window.location.search || '';
  if (hash.includes('type=recovery') || search.includes('type=recovery')) {
    pmRecovery = true;
  }
} catch(_){}

function showResetPw() {
  $('#login').hidden = true;
  $('#adminApp').hidden = true;
  const rp = $('#resetPw');
  if(rp) rp.hidden = false;
}


if ($('#resetPwForm')) {
  $('#resetPwForm').onsubmit = async e => {
    e.preventDefault();
    const p1 = $('#rpw1').value, p2 = $('#rpw2').value;
    if(p1.length < 8) return $('#rpwMsg').textContent = 'Password must be at least 8 characters';
    if(p1 !== p2) return $('#rpwMsg').textContent = 'Passwords do not match';
    $('#rpwMsg').textContent = 'Setting password...';
    const {error} = await sb.auth.updateUser({password: p1});
    if (error) {
      $('#rpwMsg').textContent = error.message;
      return;
    }
    $('#rpwMsg').textContent = '';
    $('#resetPw').hidden = true;
    pmRecovery = false;
    history.replaceState({}, document.title, location.pathname);
    toast('✓ Password updated successfully.');
    await enter();
  };
}

sb.auth.onAuthStateChange(async(event,s)=>{
  session=s;
  if(event==='SIGNED_OUT') showLogin();
  if(event==='SIGNED_IN' && $('#adminApp').hidden) {
    if(pmRecovery) {
      showResetPw();
      return;
    }
    await enter();
  }
});

async function enter(){user=session?.user;const r=await sb.from('platform_admins').select('*').eq('user_id',user.id).eq('active',true).maybeSingle();if(r.error||!r.data){await sb.auth.signOut();$('#loginMessage').textContent='This account is not an active platform administrator.';return}admin=r.data;await sb.from('platform_admins').update({last_login_at:new Date().toISOString()}).eq('user_id',user.id);$('#login').hidden=true;$('#adminApp').hidden=false;$('#adminIdentity').textContent=`${admin.display_name||user.email} • ${admin.admin_role}`;bindNav();history.replaceState({admin:true,route:'dashboard'},'');navigate('dashboard',false)}
function bindNav(){$$('[data-route]').forEach(b=>b.onclick=()=>navigate(b.dataset.route));$('#drawerToggle').onclick=$('#mobileMenu').onclick=()=>$('#adminDrawer').classList.toggle('open');$('#adminLogout').onclick=()=>sb.auth.signOut();window.navigate=navigate}
window.addEventListener('popstate',async e=>{if($('#adminModal')?.open){$('#adminModal').close();return}const target=e.state?.route;if(target){handlingPop=true;try{await navigate(target,false)}finally{handlingPop=false}}});
async function navigate(next=route,push=true){if(push&&next!==route&&!handlingPop)history.pushState({admin:true,route:next},'');route=next;$('#adminDrawer').classList.remove('open');$$('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));$('#pageToolbar').innerHTML='';loading();try{if(route==='dashboard')await dashboard();if(route==='companies')await companyPage();if(route==='plans')await planPage();if(route==='accounts')await accountPage();if(route==='usage')await usagePage();if(route==='storage')await storagePage();if(route==='ai')await aiPage();if(route==='tickets')await ticketPage();if(route==='incidents')await incidentPage();if(route==='backups')await backupPage();if(route==='legal')await legalPage();if(route==='audit')await auditPage();if(route==='qa')await qaPage();if(route==='settings')await settingsPage()}catch(e){errorView(e)}}
async function filteredRoute(next,render){if(next!==route&&!handlingPop)history.pushState({admin:true,route:next},'');route=next;$('#adminDrawer').classList.remove('open');$$('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));$('#pageToolbar').innerHTML='';loading();try{await render()}catch(e){errorView(e)}}
function toolbar(title,subtitle,actions=''){$('#pageToolbar').innerHTML=`<section class="page-toolbar"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="toolbar-actions">${actions}</div></section>`}
async function dashboard(){toolbar('Command Center','Platform operations at a glance');const[r,note]=await Promise.all([sb.rpc('control_dashboard'),sb.from('platform_notifications').select('*').is('read_at',null).order('created_at',{ascending:false}).limit(12)]);if(r.error)throw r.error;const x=r.data,k=(label,value,routeName,detail,icon)=>`<button class="admin-kpi" onclick="navigate('${routeName}')"><i>${icon}</i><span>${label}</span><strong>${typeof value==='string'?value:fmtNum(value)}</strong><small>${detail||'Tap to open'}</small></button>`;$('#adminContent').innerHTML=`<div class="command-kpis">${k('Companies',x.companies_total,'companies',`${x.companies_active} active`,'▦')}${k('Accounts',x.workers,'accounts',`${x.owners} owners`,'♙')}${k('Storage',fmtBytes(x.storage_bytes),'storage',`${x.files} files`,'▤')}${k('Gemini & AI',x.ai_requests_month,'ai','requests this month','✦')}${k('Complaints',x.open_tickets,'tickets',`${x.critical_tickets} critical`,'◉')}${k('Incidents',x.open_incidents,'incidents',`${x.critical_incidents} critical`,'⚠')}</div><div class="command-layout"><section class="command-panel"><div class="panel-head"><div><small>TENANT LIFECYCLE</small><h2>Company Status</h2></div><button onclick="navigate('companies')">Manage</button></div><div class="lifecycle-list"><button onclick="openCompanyStatus('active')"><span>Active</span><b>${fmtNum(x.companies_active)}</b></button><button onclick="openCompanyStatus('trial')"><span>Trial</span><b>${fmtNum(x.companies_trial)}</b></button><button onclick="openCompanyStatus('past_due')"><span>Past due</span><b>${fmtNum(x.companies_past_due)}</b></button><button onclick="openCompanyStatus('suspended')"><span>Suspended</span><b>${fmtNum(x.companies_suspended)}</b></button><button onclick="navigate('companies')"><span>Complimentary</span><b>${fmtNum(x.complimentary)}</b></button></div></section><section class="command-panel"><div class="panel-head"><div><small>QUICK ACTIONS</small><h2>Administrator Tools</h2></div></div><div class="quick-grid"><button onclick="navigate('companies')">▦<span>Manage Companies</span></button><button onclick="inviteOwner()">＋<span>Invite Owner</span></button><button onclick="navigate('plans')">◇<span>Plans & Limits</span></button><button onclick="navigate('usage')">◒<span>Usage Controls</span></button><button onclick="navigate('backups')">↻<span>Backup Evidence</span></button><button onclick="navigate('legal')">§<span>Legal & Deletion</span></button><button onclick="navigate('qa')">✓<span>QA Lab</span></button></div></section></div><section class="command-panel alerts-panel"><div class="panel-head"><div><small>DASHBOARD ALERTS</small><h2>Needs Attention</h2></div><button onclick="markNotificationsRead()">Mark all read</button></div><div class="alert-list">${(note.data||[]).map(n=>`<button onclick="navigate('${n.component==='platform_support'?'tickets':'incidents'}')"><span class="alert-dot ${esc(n.severity)}"></span><div><b>${esc(n.title)}</b><small>${esc(n.body||'')} • ${date(n.created_at)}</small></div>${badge(n.severity)}</button>`).join('')||'<div class="all-clear">✓ No unread platform alert</div>'}</div></section><div class="command-footer"><span>AI failures (24h): <b>${fmtNum(x.failed_ai_24h)}</b></span><span>Latest backup evidence: <b>${date(x.latest_backup)}</b></span><button onclick="navigate('backups')">Review Recovery</button></div>`;window.openCompanyStatus=status=>filteredRoute('companies',()=>companyPage('',status))}
window.markNotificationsRead=async()=>{const r=await sb.from('platform_notifications').update({read_at:new Date().toISOString()}).is('read_at',null);if(r.error)return toast(r.error.message);dashboard()};
async function loadPlans(){const r=await sb.from('subscription_plans').select('*').order('price_monthly');if(r.error)throw r.error;plans=r.data||[]}
async function companyPage(search='',status=''){toolbar('Companies','Activate, suspend, assign plans and grant free access',`<input id="companySearch" placeholder="Search companies" value="${esc(search)}"><select id="companyStatus"><option value="">All statuses</option>${['trial','active','past_due','suspended','cancelled','deletion_pending'].map(x=>`<option ${x===status?'selected':''}>${x}</option>`).join('')}</select><button onclick="reloadCompanies()">Search</button>`);await loadPlans();const r=await sb.rpc('control_companies',{p_search:search||null,p_status:status||null});if(r.error)throw r.error;companies=r.data||[];$('#adminContent').innerHTML=`<div class="grid">${companies.map(companyCard).join('')||'<div class="empty">No companies found.</div>'}</div>`;window.reloadCompanies=()=>companyPage($('#companySearch').value,$('#companyStatus').value)}
function companyCard(c){return`<article class="card company-card"><div class="company-head"><div><h3>${esc(c.name)}</h3><small>${esc(c.plan_name||'No plan')} • ${date(c.created_at)}</small></div>${badge(c.status)}</div><dl><div><dt>Workers</dt><dd>${c.workers}</dd></div><div><dt>Owners</dt><dd>${c.owners}</dd></div><div><dt>Plants</dt><dd>${c.plants}</dd></div><div><dt>Files</dt><dd>${c.files}</dd></div><div><dt>Storage</dt><dd>${fmtBytes(c.storage_bytes)}</dd></div><div><dt>AI month</dt><dd>${c.ai_requests_month}</dd></div><div><dt>Complaints</dt><dd>${c.open_tickets}</dd></div><div><dt>Incidents</dt><dd>${c.open_incidents}</dd></div></dl>${c.access_type!=='paid'?`<p>${badge(c.access_type)} until ${date(c.complimentary_ends_at)}</p>`:''}<div class="company-controls"><label>Plan<select id="cp-${c.organization_id}">${plans.map(p=>`<option value="${p.code}" ${p.code===c.plan_code?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Status<select id="cs-${c.organization_id}">${['trial','active','past_due','suspended','cancelled','deletion_pending'].map(x=>`<option ${x===c.status?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="actions"><button class="primary" onclick="applyCompany('${c.organization_id}')">Apply</button><button onclick="complimentary('${c.organization_id}')">Free Access</button><button onclick="companyUsage('${c.organization_id}')">Usage</button><button onclick="companyTickets('${c.organization_id}')">Complaints</button><button onclick="quotaOverride('${c.organization_id}')">Limit Override</button><button onclick="featureBlocks('${c.organization_id}')">Feature Blocks</button></div></article>`}
window.applyCompany=async id=>{const status=$(`#cs-${id}`).value,plan=$(`#cp-${id}`).value,reason=prompt('Reason/internal note:','Platform administrator update')||'Platform administrator update';if(['suspended','cancelled','deletion_pending'].includes(status)&&prompt(`Type ${status.toUpperCase()} to confirm:`)!==status.toUpperCase())return;const r=await sb.rpc('platform_set_company',{p_organization_id:id,p_status:status,p_plan_code:plan,p_reason:reason});if(r.error)return toast(r.error.message);toast('Company updated');companyPage()};
window.complimentary=id=>openModal('Grant Complimentary Access',`<div class="form-grid"><label>Access type<select name="type"><option>complimentary</option><option>internal</option><option>manual</option></select></label><label>Ends at (blank = permanent)<input name="ends" type="datetime-local"></label><label class="span-2">Reason<textarea name="reason" required></textarea></label><label class="span-2"><input name="never" type="checkbox" checked> Never auto-suspend from billing state</label></div>`,async fd=>{const r=await sb.rpc('control_set_complimentary',{p_organization_id:id,p_access_type:fd.get('type'),p_ends_at:fd.get('ends')||null,p_reason:fd.get('reason'),p_never_suspend:fd.get('never')==='on'});if(r.error)throw r.error;toast('Complimentary access granted');companyPage()});
window.quotaOverride=id=>openModal('Add Quota Override',`<div class="form-grid"><label>Metric<select name="metric"><option>ai_requests</option><option>ai_input_tokens</option><option>ai_output_tokens</option><option>bandwidth_bytes</option><option>storage_bytes</option><option>workers</option><option>plants</option></select></label><label>Type<select name="type"><option>bonus</option><option>absolute</option><option>block</option></select></label><label>Value<input name="value" type="number"></label><label>Ends at<input name="ends" type="datetime-local"></label><label class="span-2">Reason<textarea name="reason" required></textarea></label></div>`,async fd=>{const r=await sb.from('quota_overrides').insert({organization_id:id,metric:fd.get('metric'),override_type:fd.get('type'),value:Number(fd.get('value'))||null,ends_at:fd.get('ends')||null,reason:fd.get('reason'),created_by:user.id});if(r.error)throw r.error;await logAdmin('quota_override_created','organization',id,id,fd.get('reason'));toast('Override saved')});
window.featureBlocks=id=>openModal('Company Feature Blocks',`<div class="form-grid"><label>Feature<select name="feature"><option>gemini</option><option>deep_search</option><option>vision_scanner</option><option>condition_analysis</option><option>uploads</option></select></label><label>Action<select name="blocked"><option value="true">Block</option><option value="false">Allow / remove block</option></select></label><label>Expires at<input name="expires" type="datetime-local"></label><label class="span-2">Reason<textarea name="reason" required></textarea></label></div>`,async fd=>{const feature=fd.get('feature'),blocked=fd.get('blocked')==='true';if(blocked){const r=await sb.from('company_feature_blocks').upsert({organization_id:id,feature,blocked:true,reason:fd.get('reason'),blocked_by:user.id,expires_at:fd.get('expires')||null,updated_at:new Date().toISOString()});if(r.error)throw r.error}else{const r=await sb.from('company_feature_blocks').delete().eq('organization_id',id).eq('feature',feature);if(r.error)throw r.error}await logAdmin(blocked?'feature_blocked':'feature_unblocked','organization',id,id,fd.get('reason'),{feature});toast('Feature control updated')});window.companyUsage=id=>filteredRoute('usage',()=>usagePage(id));window.companyTickets=id=>filteredRoute('tickets',()=>ticketPage(id));
async function planPage(){toolbar('Plans & Packages','Create, edit, clone, activate or archive package definitions','<button class="primary" onclick="editPlan()">＋ Add Plan</button>');await loadPlans();$('#adminContent').innerHTML=`<div class="grid">${plans.map(p=>`<article class="card plan-card ${p.active?'':'inactive'}"><div class="company-head"><div><h3>${esc(p.name)}</h3><small>${esc(p.code)}</small></div>${badge(p.active?'active':'archived')}</div><h2>${p.currency} ${p.price_monthly}/month</h2><dl><div><dt>Workers</dt><dd>${p.max_workers}</dd></div><div><dt>Plants</dt><dd>${p.max_plants}</dd></div><div><dt>Storage</dt><dd>${fmtBytes(p.max_storage_bytes)}</dd></div><div><dt>Bandwidth</dt><dd>${fmtBytes(p.max_bandwidth_bytes_month)}</dd></div><div><dt>AI requests</dt><dd>${fmtNum(p.ai_requests_month)}</dd></div><div><dt>Retention</dt><dd>${p.retention_days} days</dd></div></dl><div class="actions"><button onclick="editPlan('${p.code}')">Edit</button><button onclick="clonePlan('${p.code}')">Clone</button><button onclick="togglePlan('${p.code}',${p.active})">${p.active?'Archive':'Activate'}</button></div></article>`).join('')}</div>`}
window.editPlan=code=>{const p=plans.find(x=>x.code===code)||{features:{gemini:true,exports:true},active:true,currency:'USD'};openModal(code?'Edit Plan':'Add Plan',planForm(p),fd=>savePlan(fd))};window.clonePlan=code=>{const p={...plans.find(x=>x.code===code),code:`${code}-copy`,name:`${plans.find(x=>x.code===code).name} Copy`};openModal('Clone Plan',planForm(p),fd=>savePlan(fd))};
function planForm(p){return`<div class="form-grid"><label>Code<input name="code" value="${esc(p.code||'')}" required></label><label>Name<input name="name" value="${esc(p.name||'')}" required></label><label class="span-2">Description<textarea name="description">${esc(p.description||'')}</textarea></label><label>Monthly price<input name="monthly" type="number" step=".01" value="${p.price_monthly||0}"></label><label>Yearly price<input name="yearly" type="number" step=".01" value="${p.price_yearly||0}"></label>${[['workers','Workers',p.max_workers],['plants','Plants',p.max_plants],['storage','Storage bytes',p.max_storage_bytes],['bandwidth','Bandwidth bytes/month',p.max_bandwidth_bytes_month],['files','Maximum files',p.max_files],['file_size','Maximum file bytes',p.max_file_bytes],['ai_month','AI requests/month',p.ai_requests_month],['ai_day','AI requests/day',p.ai_requests_day],['ai_minute','AI requests/min/user',p.ai_requests_minute_user],['input_tokens','AI input tokens',p.ai_input_tokens_month],['output_tokens','AI output tokens',p.ai_output_tokens_month],['retention','Retention days',p.retention_days]].map(x=>`<label>${x[1]}<input name="${x[0]}" type="number" value="${x[2]||0}"></label>`).join('')}
<div class="span-2" style="background:var(--card-bg);padding:15px;border-radius:8px;border:1px solid var(--border);margin-bottom:10px;">
  <h4 style="margin:0 0 10px 0;font-size:13px;color:var(--text)">Enterprise Modules</h4>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
    <label><input name="feat_analytics" type="checkbox" ${p.features?.analytics?'checked':''}> Advanced Analytics & KPIs</label>
    <label><input name="feat_safety" type="checkbox" ${p.features?.safety_loto?'checked':''}> Safety & LOTO</label>
    <label><input name="feat_predictive" type="checkbox" ${p.features?.predictive_maintenance?'checked':''}> Predictive Maintenance (Meters)</label>
    <label><input name="feat_finance" type="checkbox" ${p.features?.finance_labor?'checked':''}> Financials (Labor Rates & Costs)</label>
    <label><input name="feat_procurement" type="checkbox" ${p.features?.procurement_requests?'checked':''}> Procurement & Material Requests</label>
  </div>
</div>
<label class="span-2">Additional Features JSON<textarea name="features">${esc(JSON.stringify(p.features||{},null,2))}</textarea></label><label><input name="active" type="checkbox" ${p.active!==false?'checked':''}> Active</label></div>`}
async function savePlan(fd){
let features;
try {
  features = JSON.parse(fd.get('features') || '{}');
  // Inject the enterprise toggles into the features object
  features.analytics = fd.get('feat_analytics') === 'on';
  features.safety_loto = fd.get('feat_safety') === 'on';
  features.predictive_maintenance = fd.get('feat_predictive') === 'on';
  features.finance_labor = fd.get('feat_finance') === 'on';
  features.procurement_requests = fd.get('feat_procurement') === 'on';
} catch {
  throw Error('Features JSON is invalid');
}const n=k=>Number(fd.get(k))||0,r=await sb.rpc('control_save_plan',{p_code:fd.get('code'),p_name:fd.get('name'),p_description:fd.get('description'),p_price_monthly:n('monthly'),p_price_yearly:n('yearly'),p_max_workers:n('workers'),p_max_plants:n('plants'),p_storage:n('storage'),p_bandwidth:n('bandwidth'),p_max_files:n('files'),p_max_file:n('file_size'),p_ai_month:n('ai_month'),p_ai_day:n('ai_day'),p_ai_minute:n('ai_minute'),p_input_tokens:n('input_tokens'),p_output_tokens:n('output_tokens'),p_retention:n('retention'),p_features:features,p_active:fd.get('active')==='on'});if(r.error)throw r.error;toast('Plan saved');planPage()}
window.togglePlan=async(code,active)=>{const p=plans.find(x=>x.code===code);p.active=!active;const fd=new FormData();Object.entries({code:p.code,name:p.name,description:p.description,monthly:p.price_monthly,yearly:p.price_yearly,workers:p.max_workers,plants:p.max_plants,storage:p.max_storage_bytes,bandwidth:p.max_bandwidth_bytes_month,files:p.max_files,file_size:p.max_file_bytes,ai_month:p.ai_requests_month,ai_day:p.ai_requests_day,ai_minute:p.ai_requests_minute_user,input_tokens:p.ai_input_tokens_month,output_tokens:p.ai_output_tokens_month,retention:p.retention_days,features:JSON.stringify(p.features)}).forEach(([k,v])=>fd.set(k,v));if(p.active)fd.set('active','on');await savePlan(fd)};
async function accountPage(search=''){toolbar('Accounts','Invite owners, reset access, deactivate, recover or delete eligible accounts',`<input id="accountSearch" placeholder="Email or name" value="${esc(search)}"><button onclick="accountPage($('#accountSearch').value)">Search</button><button class="primary" onclick="inviteOwner()">Invite Owner</button>`);const r=await sb.rpc('control_accounts',{p_search:search||null});if(r.error)throw r.error;accounts=r.data||[];$('#adminContent').innerHTML=`<div class="table-wrap"><table><thead><tr><th>User</th><th>Memberships</th><th>Created/Last sign-in</th><th>Status</th><th>Actions</th></tr></thead><tbody>${accounts.map(a=>`<tr><td><b>${esc(a.full_name||a.email)}</b><small>${esc(a.email)}<br>${a.user_id}</small></td><td>${(a.companies||[]).map(c=>`${esc(c.company)} — ${badge(c.role)}`).join('<br>')||'None'}</td><td>${date(a.created_at)}<small>${date(a.last_sign_in_at)}</small></td><td>${a.banned_until?badge('suspended'):badge('active')}</td><td><div class="actions"><button onclick="resetAccount('${a.email}')">Reset Password</button><button onclick="accountAction('${a.user_id}','${a.banned_until?'unban_user':'ban_user'}')">${a.banned_until?'Recover':'Deactivate'}</button><button class="danger" onclick="accountAction('${a.user_id}','delete_user')">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`}
window.inviteOwner=()=>openModal('Invite New Company Owner',`<div class="form-grid"><label class="span-2">Owner email<input name="email" type="email" required></label><p class="span-2">The recipient creates their account and then creates their own isolated company workspace.</p></div>`,async fd=>{await adminApi({action:'invite_owner',email:fd.get('email'),redirect_to:CUSTOMER_APP_URL});toast('Owner invitation sent')});window.resetAccount=async email=>{await adminApi({action:'reset_password',email});toast('Password reset email requested')};window.accountAction=async(uid,action)=>{
  const reason=prompt('Administrative reason:')||'Platform Admin override';
  if(action==='delete_user'){
    const conf=prompt('Type DELETE USER to permanently delete this account:');
    if(conf!=='DELETE USER')return;
    
    // VERY LOUD ALERT SO WE KNOW THIS CODE IS RUNNING
    alert('Attempting to delete user ID: ' + uid);
    
    toast('Deleting user...');
    try {
        const r=await sb.rpc('platform_delete_user',{p_user_id:uid, p_reason:reason});
        
        // Show EXACTLY what Supabase returns
        alert('Supabase returned: ' + JSON.stringify(r));
        
        if(r.error) return toast(r.error.message);
        if(r.data !== 'Success') return toast('Error: ' + r.data);
        
        toast('User permanently deleted');
    } catch (err) {
        alert('CRITICAL ERROR: ' + err.message);
    }
  } else {
    const ban = (action==='ban_user');
    const r=await sb.rpc('platform_ban_user',{p_user_id:uid, p_reason:reason, p_ban:ban});
    if(r.error) return toast(r.error.message);
    toast(ban ? 'User suspended' : 'User access restored');
  }
  setTimeout(accountPage, 1000);
};
async function usagePage(orgId=null){if(!companies.length){const c=await sb.rpc('control_companies',{p_search:null,p_status:null});companies=c.data||[]}toolbar('Usage & Quotas','Per-company counters, limits, bonuses and auditable corrections',`<button onclick="usageAdjustment('${orgId||''}')">Adjust Usage</button>`);const r=await sb.rpc('control_usage',{p_organization_id:orgId||null});if(r.error)throw r.error;$('#adminContent').innerHTML=`<div class="card">${(r.data||[]).map(x=>`<div class="usage-row"><div><b>${esc(x.company)}</b><small>${esc(x.metric)} • ${x.period_start}</small></div><div>${meter(x.quantity,x.plan_limit)}<small>${fmtNum(x.quantity)} / ${x.plan_limit==null?'Custom':fmtNum(x.plan_limit)}</small></div><button onclick="usageAdjustment('${x.organization_id}','${esc(x.metric)}')">Adjust</button></div>`).join('')||'<div class="empty">No current usage counters.</div>'}</div>`}
window.usageAdjustment=(orgId='',metric='ai_requests')=>openModal('Auditable Usage Adjustment',`<div class="form-grid"><label>Company<select name="org">${companies.length?companies.map(c=>`<option value="${c.organization_id}" ${c.organization_id===orgId?'selected':''}>${esc(c.name)}</option>`).join(''):'<option value="'+orgId+'">Selected company</option>'}</select></label><label>Metric<input name="metric" value="${esc(metric)}"></label><label>Quantity (+ bonus / - correction)<input name="quantity" type="number" required></label><label class="span-2">Reason<textarea name="reason" required></textarea></label></div>`,async fd=>{const r=await sb.rpc('control_adjust_usage',{p_organization_id:fd.get('org'),p_metric:fd.get('metric'),p_quantity:Number(fd.get('quantity')),p_reason:fd.get('reason')});if(r.error)throw r.error;toast('Usage adjusted');usagePage(fd.get('org'))});
async function storagePage(orgId=null){if(!companies.length){const c=await sb.rpc('control_companies',{p_search:null,p_status:null});companies=c.data||[]}toolbar('Storage Management','Company files, categories, sizes, secure access and quarantine',`<select id="storageOrg"><option value="">All companies</option>${companies.map(c=>`<option value="${c.organization_id}" ${c.organization_id===orgId?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button onclick="storagePage($('#storageOrg').value)">Filter</button>`);const r=await sb.rpc('control_storage',{p_organization_id:orgId||null});if(r.error)throw r.error;$('#adminContent').innerHTML=`<div class="table-wrap"><table><thead><tr><th>File</th><th>Company</th><th>Category/type</th><th>Size/date</th><th>Actions</th></tr></thead><tbody>${(r.data||[]).map(f=>`<tr><td><b>${esc(f.file_name)}</b><small>${esc(f.object_path)}</small></td><td>${esc(f.company)}<small>${esc(f.uploader||f.uploaded_by)}</small></td><td>${esc(f.category||'—')}<small>${esc(f.mime_type||'')}</small></td><td>${fmtBytes(f.size_bytes)}<small>${date(f.created_at)}</small></td><td><div class="actions"><button onclick="storageAction('${f.file_id}','storage_signed_url')">View</button><button onclick="storageAction('${f.file_id}','storage_quarantine')">Quarantine</button><button class="danger" onclick="storageAction('${f.file_id}','storage_delete')">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`}
window.storageAction=async(id,action)=>{let reason='',confirmation='';if(action!=='storage_signed_url')reason=prompt('Reason:')||'';if(action==='storage_delete'){confirmation=prompt('Type DELETE FILE:');if(confirmation!=='DELETE FILE')return}try{const r=await adminApi({action,file_id:id,reason,confirmation});if(r.url)open(r.url,'_blank');else{toast('Storage action completed');storagePage()}}catch(e){toast(e.message)}};
async function aiPage(orgId=null){toolbar('Gemini & AI','Company/user usage, tokens, models, latency, errors and controls');const r=await sb.rpc('control_ai_usage',{p_organization_id:orgId||null});if(r.error)throw r.error;const rows=r.data||[],totalIn=rows.reduce((n,x)=>n+(x.input_tokens||0),0),totalOut=rows.reduce((n,x)=>n+(x.output_tokens||0),0),failed=rows.filter(x=>x.status==='failed').length;$('#adminContent').innerHTML=`<div class="kpi-grid">${[['Requests',rows.length],['Input tokens',totalIn],['Output tokens',totalOut],['Failures',failed]].map(x=>`<article class="kpi"><small>${x[0]}</small><strong>${fmtNum(x[1])}</strong></article>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Company/user</th><th>Provider/model</th><th>Mode/status</th><th>Tokens/latency</th><th>Error/date</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.company)}<small>${esc(x.user_name||x.user_id)}</small></td><td>${esc(x.provider||'')}<small>${esc(x.model||'')}</small></td><td>${esc(x.mode||'')}<br>${badge(x.status)}</td><td>${fmtNum(x.input_tokens)} in / ${fmtNum(x.output_tokens)} out<small>${x.latency_ms||0} ms</small></td><td>${esc(x.error_code||'—')}<small>${date(x.created_at)}</small></td></tr>`).join('')}</tbody></table></div>`}
async function ticketPage(orgId=null){toolbar('Complaints & App Support','Acknowledge, investigate, reply, assign and resolve customer complaints',`<button class="primary" onclick="newTicket('${orgId||''}')">＋ New Ticket</button>`);let q=sb.from('platform_support_tickets').select('*,organizations(name)').order('updated_at',{ascending:false}).limit(300);if(orgId)q=q.eq('organization_id',orgId);const r=await q;if(r.error)throw r.error;$('#adminContent').innerHTML=`<div class="grid">${(r.data||[]).map(t=>`<article class="card ticket ${esc(t.priority)}"><div class="company-head"><div><h3>#${t.ticket_number} ${esc(t.subject)}</h3><small>${esc(t.organizations?.name||t.owner_email||'Platform')} • ${date(t.updated_at)}</small></div>${badge(t.status)}</div><p>${esc(t.description.slice(0,260))}</p><div class="actions"><button class="primary" onclick="openTicket('${t.id}')">Open</button><button onclick="quickTicket('${t.id}','acknowledged')">Acknowledge</button><button onclick="quickTicket('${t.id}','resolved')">Resolve</button></div></article>`).join('')||'<div class="empty">No complaints.</div>'}</div>`}
window.newTicket=orgId=>openModal('Create Platform Ticket',`<div class="form-grid"><label>Company ID<input name="org" value="${esc(orgId)}"></label><label>Category<select name="category"><option>application</option><option>billing</option><option>account</option><option>storage</option><option>ai</option><option>data</option><option>other</option></select></label><label>Priority<select name="priority"><option>low</option><option selected>medium</option><option>high</option><option>critical</option></select></label><label class="span-2">Subject<input name="subject" required></label><label class="span-2">Description<textarea name="description" required></textarea></label></div>`,async fd=>{const r=await sb.from('platform_support_tickets').insert({organization_id:fd.get('org')||null,opened_by:user.id,owner_email:user.email,category:fd.get('category'),priority:fd.get('priority'),subject:fd.get('subject'),description:fd.get('description'),app_version:'admin-created'});if(r.error)throw r.error;toast('Ticket created');ticketPage()});
window.openTicket=async id=>{const[t,m]=await Promise.all([sb.from('platform_support_tickets').select('*,organizations(name)').eq('id',id).single(),sb.from('platform_support_messages').select('*').eq('ticket_id',id).order('created_at')]);if(t.error)throw t.error;currentTicket=t.data;openModal(`#${t.data.ticket_number} ${t.data.subject}`,`<div class="ticket-detail"><p>${esc(t.data.description)}</p><div class="form-grid"><label>Status<select name="status">${['new','acknowledged','investigating','waiting_customer','resolved','closed'].map(x=>`<option ${x===t.data.status?'selected':''}>${x}</option>`).join('')}</select></label><label>Priority<select name="priority">${['low','medium','high','critical'].map(x=>`<option ${x===t.data.priority?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="messages">${(m.data||[]).map(x=>`<div class="message ${x.internal?'internal':''}">${esc(x.message)}<small>${date(x.created_at)} ${x.internal?'• Internal':''}</small></div>`).join('')}</div><label>Reply<textarea name="reply"></textarea></label><label><input name="internal" type="checkbox"> Internal administrator note</label><label>Resolution<textarea name="resolution">${esc(t.data.resolution||'')}</textarea></label></div>`,async fd=>{const status=fd.get('status'),u=await sb.from('platform_support_tickets').update({status,priority:fd.get('priority'),resolution:fd.get('resolution')||null,resolved_at:status==='resolved'?new Date().toISOString():null,updated_at:new Date().toISOString(),assigned_to:user.id}).eq('id',id);if(u.error)throw u.error;if(fd.get('reply')){const msg=await sb.from('platform_support_messages').insert({ticket_id:id,user_id:user.id,message:fd.get('reply'),internal:fd.get('internal')==='on'});if(msg.error)throw msg.error}toast('Ticket updated');ticketPage()})};window.quickTicket=async(id,status)=>{const r=await sb.from('platform_support_tickets').update({status,assigned_to:user.id,resolved_at:status==='resolved'?new Date().toISOString():null,updated_at:new Date().toISOString()}).eq('id',id);if(r.error)return toast(r.error.message);ticketPage()};
async function incidentPage(){toolbar('Incidents & Monitoring','Database, Storage, Edge Function, Gemini and service failures');const r=await sb.from('system_incidents').select('*,organizations(name)').order('last_seen_at',{ascending:false}).limit(500);if(r.error)throw r.error;$('#adminContent').innerHTML=`<div class="grid">${(r.data||[]).map(i=>`<article class="card incident ${esc(i.severity)}"><div class="company-head"><div><h3>${esc(i.component)} — ${esc(i.event_type)}</h3><small>${esc(i.organizations?.name||'Platform')} • ${date(i.last_seen_at)}</small></div>${badge(i.status)}</div><p>${esc(i.message)}</p><div class="actions"><button onclick="incidentStatus('${i.id}','acknowledged')">Acknowledge</button><button class="success" onclick="incidentStatus('${i.id}','resolved')">Resolve</button><button onclick="incidentStatus('${i.id}','open')">Reopen</button></div></article>`).join('')||'<div class="empty">No incidents.</div>'}</div>`}window.incidentStatus=async(id,status)=>{const r=await sb.rpc('platform_update_incident',{p_incident_id:id,p_status:status});if(r.error)return toast(r.error.message);incidentPage()};
async function backupPage(){toolbar('Backups & Recovery','Supabase managed backup records, inventories and restore drills',`<button onclick="requestBackup()">Request/Record Backup</button><button class="primary" onclick="newRestoreDrill()">Plan Restore Drill</button>`);const[b,d]=await Promise.all([sb.from('backup_jobs').select('*').order('created_at',{ascending:false}),sb.from('restore_drills').select('*,backup_jobs(backup_reference)').order('created_at',{ascending:false})]);$('#adminContent').innerHTML=`<div class="section-grid"><article class="card"><h2>Backup jobs</h2>${(b.data||[]).map(x=>`<div class="usage-row"><div><b>${esc(x.job_type)}</b><small>${esc(x.provider)} • ${date(x.created_at)}</small></div><div>${badge(x.status)}<small>${esc(x.backup_reference||x.error||'')}</small></div><button onclick="editBackup('${x.id}')">Update</button></div>`).join('')||'<p>No backup records.</p>'}</article><article class="card"><h2>Restore drills</h2>${(d.data||[]).map(x=>`<div class="usage-row"><div><b>${esc(x.environment)}</b><small>${date(x.scheduled_at)}</small></div><div>${badge(x.status)}<small>RPO ${x.rpo_minutes??'—'} / RTO ${x.rto_minutes??'—'} min</small></div><button onclick="editDrill('${x.id}')">Update</button></div>`).join('')||'<p>No restore drills.</p>'}</article></div><div class="card"><p>This dashboard records Supabase managed backup/PITR evidence and restore drills. It does not expose database credentials or execute privileged database restores from the browser.</p></div>`}
