window.newRestoreDrill=()=>openModal('Plan Restore Drill',`<div class="form-grid"><label>Environment<input name="env" value="non_production"></label><label>Scheduled<input name="scheduled" type="datetime-local"></label><label class="span-2">Notes<textarea name="notes"></textarea></label></div>`,async fd=>{const r=await sb.from('restore_drills').insert({environment:fd.get('env'),scheduled_at:fd.get('scheduled')||null,notes:fd.get('notes'),status:'planned'});if(r.error)throw r.error;toast('Restore drill planned');backupPage()});window.editBackup=id=>toast('Use the backup provider result to update this record in the next operator step.');window.editDrill=id=>openModal('Complete Restore Drill',`<div class="form-grid"><label>Status<select name="status"><option>running</option><option>passed</option><option>failed</option><option>cancelled</option></select></label><label>RPO minutes<input name="rpo" type="number"></label><label>RTO minutes<input name="rto" type="number"></label><label><input name="db" type="checkbox"> Database verified</label><label><input name="storage" type="checkbox"> Storage verified</label><label class="span-2">Notes<textarea name="notes"></textarea></label></div>`,async fd=>{const r=await sb.from('restore_drills').update({status:fd.get('status'),rpo_minutes:Number(fd.get('rpo'))||null,rto_minutes:Number(fd.get('rto'))||null,database_verified:fd.get('db')==='on',storage_verified:fd.get('storage')==='on',notes:fd.get('notes'),performed_by:user.id,completed_at:['passed','failed'].includes(fd.get('status'))?new Date().toISOString():null}).eq('id',id);if(r.error)throw r.error;toast('Restore drill updated');backupPage()});
