window.publishLegal=()=>openModal('Publish Legally Approved Document',`<div class="form-grid"><label>Type<select name="type"><option>privacy</option><option>terms</option><option>acceptable_use</option><option>ai_disclosure</option><option>data_processing</option><option>retention</option><option>deletion</option></select></label><label>Version<input name="version" required></label><label class="span-2">Title<input name="title" required></label><label>Effective at<input name="effective" type="datetime-local" required></label><label>Scope<select name="scope"><option>all_users</option><option>owners</option><option>platform_admins</option></select></label><label><input name="required" type="checkbox"> Required acceptance</label><label class="span-2">Approved content<textarea name="content" rows="16" required></textarea></label></div>`,async fd=>{const r=await sb.from('legal_documents').insert({document_type:fd.get('type'),version:fd.get('version'),title:fd.get('title'),content:fd.get('content'),effective_at:new Date(fd.get('effective')).toISOString(),active:true,required:fd.get('required')==='on',acceptance_scope:fd.get('scope'),published_by:user.id,published_at:new Date().toISOString()});if(r.error)throw r.error;await logAdmin('legal_document_published','legal_document',r.data?.id||fd.get('version'),null,fd.get('title'));toast('Document published');legalPage()});window.deletionStatus=id=>openModal('Review Deletion Request',`<div class="form-grid"><label>Status<select name="status"><option>verified</option><option>scheduled</option><option>cancelled</option><option>completed</option><option>failed</option></select></label><label>Scheduled for<input name="scheduled" type="datetime-local"></label><label class="span-2">Review note<textarea name="note"></textarea></label></div>`,async fd=>{const r=await sb.from('deletion_requests').update({status:fd.get('status'),scheduled_for:fd.get('scheduled')||null,completed_at:fd.get('status')==='completed'?new Date().toISOString():null,reason:fd.get('note')||null}).eq('id',id);if(r.error)throw r.error;toast('Deletion request updated');legalPage()});
