async function qaPage(){toolbar('QA Lab','Create isolated test tenants, run automated regression and record physical-device checks',`<button class="primary" onclick="createQAEnvironment()">＋ Create QA Environment</button>`);const overview=await sb.rpc('control_qa_overview');if(overview.error)throw overview.error;const x=overview.data.summary,environments=overview.data.environments||[],runs=overview.data.runs||[];$('#adminContent').innerHTML=`<div class="kpi-grid">${[['QA environments',x.environments],['Ready',x.ready],['Test runs',x.runs],['Passed runs',x.passed_runs],['Failed/partial',x.failed_runs],['Latest run',x.latest_run?new Date(x.latest_run).toLocaleDateString():'—']].map(v=>`<article class="kpi"><small>${v[0]}</small><strong>${v[1]}</strong></article>`).join('')}</div><div class="grid">${environments.map(e=>`<article class="card qa-env"><div class="company-head"><div><h3>${esc(e.name)}</h3><small>${date(e.created_at)} • ${esc(e.organization_id||'Not created')}</small></div>${badge(e.status)}</div><p>${esc(e.last_error||'Isolated QA tenant. Never use production data for destructive tests.')}</p><div class="actions"><button class="primary" onclick="runQA('${e.id}',false)">Run Automated</button><button onclick="runQA('${e.id}',true)">Run + Gemini</button><button onclick="viewQARuns('${e.id}')">Results</button><button class="danger" onclick="deleteQA('${e.id}')">Delete QA</button></div></article>`).join('')||'<div class="empty">No QA environment. Create one to start safe regression testing.</div>'}</div><section class="command-panel qa-recent"><div class="panel-head"><div><small>RECENT RUNS</small><h2>Regression Results</h2></div></div>${runs.map(r=>`<button onclick="viewQARun('${r.id}')"><div><b>${esc(r.status.toUpperCase())}</b><small>${date(r.started_at)} • AI ${r.include_ai?'included':'not included'}</small></div><span>${r.passed} passed / ${r.failed} failed / ${r.blocked} manual</span></button>`).join('')||'<p>No runs.</p>'}</section>`}
window.createQAEnvironment=async()=>{if(!confirm('Create a fully isolated PlantMaster QA company and seven temporary role accounts?'))return;loading('Creating QA company, users and seeded records…');try{const r=await qaRunner({action:'create'});toast(`QA environment ready: ${r.name}`);qaPage()}catch(e){errorView(e,"navigate('qa')")}};
window.runQA=async(id,includeAI)=>{if(includeAI&&!confirm('This run makes real Gemini requests and consumes QA company AI quota. Continue?'))return;$('#adminContent').innerHTML=`<div class="qa-running"><span class="spinner"></span><h2>Full regression test running</h2><p>Do not close this tab. Testing role accounts, tenant isolation, writes, concurrency, limits${includeAI?', English/Urdu Gemini and condition analysis':''}.</p></div>`;try{const r=await qaRunner({action:'run',environment_id:id,include_ai:includeAI});toast(`${r.status}: ${r.passed} passed, ${r.failed} failed`);viewQARun(r.run_id)}catch(e){errorView(e,"navigate('qa')")}};
window.viewQARuns=async envId=>{const r=await sb.rpc('control_qa_environment_runs',{p_environment_id:envId});if(r.error)return toast(r.error.message);const rows=r.data||[];$('#adminContent').innerHTML=`<section class="page-toolbar"><div><h1>QA Environment Runs</h1><p>${rows.length} run(s)</p></div><button onclick="navigate('qa')">QA Lab</button></section><div class="grid">${rows.map(x=>`<article class="card"><h3>${esc(x.status)}</h3><p>${date(x.started_at)}<br>${x.passed} passed • ${x.failed} failed • ${x.blocked} manual</p><button onclick="viewQARun('${x.id}')">Open Results</button></article>`).join('')}</div>`};
window.viewQARun=async runId=>{const detail=await sb.rpc('control_qa_run_detail',{p_run_id:runId});if(detail.error)return toast(detail.error.message);const run={data:detail.data.run},results={data:detail.data.results||[]},manual={data:detail.data.manual||[]};window.currentQARun={run:run.data,results:results.data,manual:manual.data};$('#pageToolbar').innerHTML='';$('#adminContent').innerHTML=`<section class="page-toolbar"><div><h1>QA Test Results</h1><p>${esc(run.data.environment_name)} • ${date(run.data.started_at)}</p></div><div class="toolbar-actions"><button onclick="exportQA('html')">View/Print Report</button><button onclick="exportQA('json')">JSON</button><button onclick="exportQA('csv')">CSV</button><button onclick="navigate('qa')">QA Lab</button></div></section><div class="qa-summary ${esc(run.data.status)}"><div><small>STATUS</small><strong>${esc(run.data.status.toUpperCase())}</strong></div><div><small>PASSED</small><strong>${run.data.passed}</strong></div><div><small>FAILED</small><strong>${run.data.failed}</strong></div><div><small>BLOCKED / MANUAL</small><strong>${run.data.blocked}</strong></div></div><div class="qa-results">${(results.data||[]).map(x=>`<article class="qa-test ${esc(x.status)}"><span>${x.status==='passed'?'✓':x.status==='blocked'?'!':'✕'}</span><div><small>${esc(x.category)}</small><b>${esc(x.test_name)}</b><p><strong>Expected:</strong> ${esc(x.expected||'')}<br><strong>Actual:</strong> ${esc(x.error||x.actual||'')}</p></div><em>${x.duration_ms||0} ms</em></article>`).join('')}</div><section class="command-panel"><div class="panel-head"><div><small>PHYSICAL DEVICE</small><h2>Manual Checks</h2></div></div>${(manual.data||[]).map(x=>`<div class="manual-check"><div><b>${esc(x.check_name)}</b><small>${esc(x.category)} • ${esc(x.instructions)}</small></div>${badge(x.status)}<button onclick="manualQA('${x.id}','passed')">Pass</button><button onclick="manualQA('${x.id}','failed')">Fail</button></div>`).join('')}</section>`};
window.manualQA=async(id,status)=>{const notes=prompt('Result notes (optional):')||null,r=await sb.rpc('control_update_manual_check',{p_check_id:id,p_status:status,p_notes:notes});if(r.error)return toast(r.error.message);viewQARun(window.currentQARun.run.id)};
window.deleteQA=async id=>{if(prompt('This deletes only the registered QA company/users/data. Type DELETE QA ENVIRONMENT:')!=='DELETE QA ENVIRONMENT')return;loading('Deleting isolated QA records and temporary accounts…');try{await qaRunner({action:'cleanup',environment_id:id,confirmation:'DELETE QA ENVIRONMENT'});toast('QA environment deleted');qaPage()}catch(e){errorView(e,"navigate('qa')")}};
window.exportQA=type=>{const q=window.currentQARun;if(!q)return;const payload={generated_at:new Date().toISOString(),run:q.run,results:q.results,manual_checks:q.manual};if(type==='json')return saveFile(JSON.stringify(payload,null,2),'application/json',`PlantMaster-QA-${q.run.id}.json`);if(type==='csv'){const csv='category,test,status,expected,actual,error,duration_ms\r\n'+q.results.map(x=>[x.category,x.test_name,x.status,x.expected,x.actual,x.error,x.duration_ms].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');return saveFile('\ufeff'+csv,'text/csv',`PlantMaster-QA-${q.run.id}.csv`)}const w=open('','_blank');w.document.write(qaReportHTML(payload));w.document.close()};
function qaReportHTML(q){return`<!doctype html><html><head><meta charset="utf-8"><title>PlantMaster QA Report</title><style>body{font:13px Arial;max-width:1000px;margin:25px auto;padding:20px;color:#172334}table{border-collapse:collapse;width:100%}th,td{border:1px solid #aaa;padding:7px;text-align:left}.passed{color:#087f5b}.failed{color:#c2255c}@media print{button{display:none}}</style></head><body><h1>PlantMaster Full Regression Report</h1><p>${esc(q.run.environment_name)} • ${date(q.run.started_at)}</p><h2 class="${q.run.status}">${esc(q.run.status.toUpperCase())}: ${q.run.passed} passed / ${q.run.failed} failed / ${q.run.blocked} manual</h2><button onclick="print()">Print / Save PDF</button><table><thead><tr><th>Category</th><th>Test</th><th>Status</th><th>Expected</th><th>Actual/Error</th><th>ms</th></tr></thead><tbody>${q.results.map(x=>`<tr><td>${esc(x.category)}</td><td>${esc(x.test_name)}</td><td class="${esc(x.status)}">${esc(x.status)}</td><td>${esc(x.expected||'')}</td><td>${esc(x.error||x.actual||'')}</td><td>${x.duration_ms||0}</td></tr>`).join('')}</tbody></table><h2>Manual Device Checks</h2><table>${q.manual_checks.map(x=>`<tr><td>${esc(x.category)}</td><td>${esc(x.check_name)}</td><td>${esc(x.status)}</td><td>${esc(x.result_notes||x.instructions)}</td></tr>`).join('')}</table></body></html>`}
function saveFile(data,type,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function qaRunner(body){const r=await sb.functions.invoke('qa-runner',{body});if(r.error){let d='';try{d=(await r.error.context?.json())?.error||''}catch{}throw Error(d||r.error.message)}if(r.data?.error)throw Error(r.data.error);return r.data}
async function settingsPage(){toolbar('Control Center Settings','Administrator identity, roles, security and environment',`<button class="primary" onclick="editAdministrator()">＋ Add Administrator</button>`);let admins=[];const ar=await sb.rpc('control_admins');if(!ar.error)admins=ar.data||[];$('#adminContent').innerHTML=`<div class="section-grid"><article class="card"><h2>Current administrator</h2><p>${esc(admin.display_name||user.email)}</p><dl><div><dt>Role</dt><dd>${esc(admin.admin_role)}</dd></div><div><dt>User ID</dt><dd>${user.id}</dd></div><div><dt>Last login</dt><dd>${date(admin.last_login_at)}</dd></div></dl></article><article class="card"><h2>Environment</h2><p>Supabase: ${esc(SUPABASE_URL)}</p><p>Customer app: <a href="${CUSTOMER_APP_URL}" target="_blank">${CUSTOMER_APP_URL}</a></p><p>Billing: Manual plan control</p><p>Alerts: Dashboard only</p><p>Backups: Supabase managed/PITR evidence</p></article></div><div class="card"><h2>Platform Administrators</h2>${admins.map(a=>`<div class="usage-row"><div><b>${esc(a.full_name||a.email)}</b><small>${esc(a.email)} • ${a.user_id}</small></div><div>${badge(a.admin_role)} ${badge(a.active?'active':'inactive')}<small>Last login ${date(a.last_login_at)}</small></div><button onclick="editAdministrator('${a.user_id}')">Edit</button></div>`).join('')||'<p>Administrator list requires admins.manage permission.</p>'}</div><div class="card"><h2>Security requirements</h2><ul><li>No public administrator registration</li><li>Service credentials remain only in Edge Functions</li><li>Enable MFA for administrator accounts in production</li><li>Use typed confirmations for destructive actions</li><li>Usage and audit corrections remain append-only</li></ul></div>`;window.controlAdmins=admins}
window.editAdministrator=uid=>{const a=(window.controlAdmins||[]).find(x=>x.user_id===uid)||{admin_role:'support',active:true,permissions:{}};openModal(uid?'Edit Platform Administrator':'Add Platform Administrator',`<div class="form-grid"><label class="span-2">Auth User UUID<input name="uid" value="${esc(a.user_id||'')}" required></label><label>Display name<input name="name" value="${esc(a.full_name||'')}"></label><label>Role<select name="role">${['super_admin','operations','support','billing','auditor'].map(x=>`<option ${x===a.admin_role?'selected':''}>${x}</option>`).join('')}</select></label><label><input name="active" type="checkbox" ${a.active!==false?'checked':''}> Active</label><fieldset class="span-2"><legend>Explicit permissions</legend>${['companies.manage','plans.manage','accounts.view','accounts.manage','usage.view','usage.manage','storage.view','storage.manage','ai.view','ai.manage','support.manage','incidents.manage','backups.manage','legal.manage','audit.view','admins.manage'].map(x=>`<label><input type="checkbox" name="perm" value="${x}" ${a.permissions?.[x]?'checked':''}> ${x}</label>`).join('')}</fieldset></div>`,async fd=>{const permissions={};fd.getAll('perm').forEach(x=>permissions[x]=true);const r=await sb.rpc('control_save_admin',{p_user_id:fd.get('uid'),p_role:fd.get('role'),p_active:fd.get('active')==='on',p_permissions:permissions,p_display_name:fd.get('name')||null});if(r.error)throw r.error;toast('Administrator saved');settingsPage()})};
async function adminApi(body){const r=await sb.functions.invoke('platform-admin-api',{body});if(r.error){let d='';try{d=(await r.error.context?.json())?.error||''}catch{}throw Error(d||r.error.message)}if(r.data?.error)throw Error(r.data.error);return r.data}
async function logAdmin(action,target_type,target_id,organization_id,reason,details={}){await sb.from('admin_action_logs').insert({admin_user_id:user.id,action,target_type,target_id,organization_id:organization_id||null,reason:reason||null,details})}
function openModal(title,html,handler){modalHandler=handler;$('#adminModalTitle').textContent=title;$('#adminModalBody').innerHTML=html;$('#adminModalError').textContent='';const d=$('#adminModal');if(!history.state?.modal)history.pushState({admin:true,route,modal:true},'');d.showModal();return d}function closeAdminModal(){const d=$('#adminModal');if(history.state?.modal)history.back();else if(d.open)d.close()}$('#adminModalClose').onclick=$('#adminModalCancel').onclick=closeAdminModal;$('#adminModal').addEventListener('cancel',e=>{e.preventDefault();closeAdminModal()});$('#adminModalForm').onsubmit=async e=>{e.preventDefault();const b=$('#adminModalSave');b.disabled=true;b.textContent='Saving…';try{await modalHandler(new FormData(e.target));closeAdminModal()}catch(err){$('#adminModalError').textContent=err.message||String(err)}finally{b.disabled=false;b.textContent='Save'}};
if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js?v=1.3.2',{updateViaCache:'none'});init();
